-- Actual existing persisted review/activation commands; all identities/approvals/funds are rolled-back synthetic fixtures.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('d2060004-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('admin',true,'payment_verified',true))::text,true)$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-m6-confirmation-'||n||'@example.test',now()from generate_series(1,2)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,2)n;
insert into public.doctor_candidate_admissions(user_id,purpose,evidence_ref,valid_until)select pg_temp.id(n),'synthetic_fixture','disposable-m6-004:'||n,clock_timestamp()+interval'2 hours'from generate_series(1,2)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic paying owner');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(21),pg_temp.id(1),'Synthetic payment practice');
update public.doctor_edition_policy set mode='administrative_candidate',revision=revision+1,change_reason='Explicit synthetic M6-004 verification';
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,yearly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)values
(pg_temp.id(51),'synthetic-m6-004',1,'approved','EGP',2,29900,243984,0,4,false,1,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-m6-004/v1','SYNTHETIC_NOT_COMMERCIAL_APPROVAL','SYNTHETIC_NOT_LEGAL_APPROVAL');
insert into public.doctor_saas_terms_documents(terms_version_id,document_ref,content_en,content_ar)values(pg_temp.id(51),'synthetic-m6-004/v1','Synthetic fixture only; no actual payment or merchant approval.','اختبار اصطناعي فقط دون دفع فعلي أو اعتماد تاجر.');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(51),revision=2,change_reason='Disposable terms only';
insert into public.doctor_manual_payment_recipients(id,account_key,address_kind,address,beneficiary_name,instructions_en,instructions_ar,currency,currency_exponent,merchant_approval_ref)values(pg_temp.id(71),pg_temp.id(72),'ipa','synthetic-fixture-only@instapay','Synthetic fixture beneficiary','Do not transfer actual funds.','لا تحول أموالاً حقيقية.','EGP',2,'SYNTHETIC_FIXTURE_NOT_MERCHANT_APPROVAL');
update public.doctor_manual_payment_configuration set recipient_id=pg_temp.id(71),enabled=true,acceptance_mode='synthetic',activation_policy='inactive_account_on_review',activation_approval_ref='SYNTHETIC_NOT_LIVE_APPROVAL',revision=2,change_reason='Rolled-back synthetic M6-004 configuration';
create temporary table results(name text primary key,value jsonb);grant all on results to authenticated;
create temporary table moment(value timestamptz);insert into moment values(clock_timestamp()-interval'1 minute');grant select on moment to authenticated;
create function pg_temp.notice(n integer)returns jsonb language plpgsql security invoker as $$declare q jsonb;i jsonb;begin
 q:=public.doctor_create_saas_quote(pg_temp.id(51),2,0,'monthly','synthetic-m6-004/v1',pg_temp.id(200+n));
 i:=public.doctor_prepare_saas_payment((q->>'quote_id')::uuid,pg_temp.id(300+n));
 perform public.doctor_prepare_manual_payment((i->>'intent_id')::uuid,2,pg_temp.id(400+n));
 return public.doctor_submit_manual_payment((i->>'intent_id')::uuid,'SYNTHETIC-M6-CLAIM-'||n,(select value from moment),2,pg_temp.id(500+n));end $$;
create function pg_temp.confirm(p_notice_name text,command integer,minor text default'29900',unit text default'EGP',independent boolean default true,bank text default'SYNTHETIC-BANK-ENTRY')returns jsonb language sql security invoker as $$select public.doctor_review_manual_payment((select(value->>'id')::uuid from results where results.name=p_notice_name),0,'funds_verified','Synthetic independent bank check',bank,minor,unit,(select value from moment),'SYNTHETIC_BANK_RECORD_NOT_REAL_EVIDENCE',independent,pg_temp.id(command))$$;
set local role authenticated;select pg_temp.claim(1);
insert into results values('first',pg_temp.notice(1)),('second',pg_temp.notice(2));
select is((select value->>'status'from results where name='first'),'submitted','customer claim is not confirmation');
select is(public.doctor_saas_status()->>'state','unconfigured','claim and instructions create no entitlement');
select pg_temp.claim(2);
select throws_ok($$select pg_temp.confirm('first',601)$$,'42501','DOCTOR_MANUAL_REVIEW_AUTHORITY_REQUIRED','editable admin/payment metadata grants no reviewer authority');
reset role;
insert into public.doctor_manual_payment_reviewers(user_id,enabled,revision,approval_ref,valid_until)values(pg_temp.id(1),true,1,'SYNTHETIC_SELF_REVIEW_DENIAL',clock_timestamp()+interval'1 hour'),(pg_temp.id(2),true,1,'SYNTHETIC_INDEPENDENT_REVIEWER_NOT_LIVE',clock_timestamp()+interval'1 hour');
set local role authenticated;select pg_temp.claim(1);
select throws_ok($$select pg_temp.confirm('first',602)$$,'42501','DOCTOR_INDEPENDENT_REVIEW_REQUIRED','even a granted customer cannot verify their own claim');
select pg_temp.claim(2);
select throws_ok($$select pg_temp.confirm('first',603,'1')$$,'22023','DOCTOR_RECEIVED_FUNDS_VERIFICATION_REQUIRED','wrong received amount cannot confirm the frozen quote');
select throws_ok($$select pg_temp.confirm('first',604,'29900','USD')$$,'22023','DOCTOR_RECEIVED_FUNDS_VERIFICATION_REQUIRED','wrong received currency cannot confirm the quote');
select throws_ok($$select pg_temp.confirm('first',605,'29900','EGP',false)$$,'22023','DOCTOR_RECEIVED_FUNDS_VERIFICATION_REQUIRED','customer evidence cannot replace an independent bank check');
insert into results values('verified',pg_temp.confirm('first',610));
select is((select value->>'status'from results where name='verified'),'funds_verified','independent evidence persists as funds verification');
select is((select value->'period_id'from results where name='verified'),'null'::jsonb,'funds acceptance is separate from subscription activation');
select is(pg_temp.confirm('first',610),(select value from results where name='verified'),'lost acknowledgement replays the original accepted receipt');
select throws_ok($$select pg_temp.confirm('second',613,'29900','EGP',true,' synthetic-bank-entry ')$$,'23505',null,'normalized beneficiary bank reference cannot fund another notice');
reset role;
select is((select count(*)::integer from public.doctor_manual_received_funds),1,'duplicate bank evidence creates one received-funds entry');
select is((select count(*)::integer from public.doctor_saas_periods),0,'verified funds alone create no period');
select ok(not exists(select 1 from doctor_private.command_receipts where command_key in(pg_temp.id(601),pg_temp.id(602),pg_temp.id(603),pg_temp.id(604),pg_temp.id(605),pg_temp.id(613))),'denied verification leaves no success receipt');
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_saas_status()->>'state','unconfigured','subscriber status remains unconfigured until separate activation');
select throws_ok($$select public.doctor_activate_manual_payment(((select value from results where name='first')->>'id')::uuid,1,pg_temp.id(619))$$,'42501','DOCTOR_INDEPENDENT_REVIEW_REQUIRED','customer cannot activate their own independently reviewed notice');
select pg_temp.claim(2);
insert into results values('activated',public.doctor_activate_manual_payment(((select value from results where name='first')->>'id')::uuid,1,pg_temp.id(620)));
select is((select value->>'status'from results where name='activated'),'activated','separate configured synthetic activation appends its own event');
select is(public.doctor_activate_manual_payment(((select value from results where name='first')->>'id')::uuid,1,pg_temp.id(620)),(select value from results where name='activated'),'lost activation acknowledgement replays the same period receipt');
select throws_ok($$select public.doctor_activate_manual_payment(((select value from results where name='first')->>'id')::uuid,1,pg_temp.id(621))$$,'40001','DOCTOR_MANUAL_REVIEW_CONFLICT','fresh stale-revision activation cannot create another period');
select is(pg_temp.confirm('first',610)->>'status','funds_verified','old verification receipt remains historical after activation');
select is(public.doctor_manual_payments(p_notice=>((select value from results where name='first')->>'id')::uuid,p_review_queue=>true)->>'status','activated','old acknowledgement cannot undo the current authoritative activation');
reset role;
select is((select count(*)::integer from public.doctor_saas_periods where kind='manual_paid'),1,'exact activation retries retain one period');
select is((select count(*)::integer from public.doctor_manual_payment_reviews where notice_id=((select value from results where name='first')->>'id')::uuid),2,'funds verification and activation have separate immutable review events');
select is((select count(*)::integer from public.doctor_manual_payment_reviews where notice_id=((select value from results where name='second')->>'id')::uuid),0,'duplicate bank evidence leaves the second claim unconfirmed');
select is((select p.ends_at from public.doctor_saas_periods p where p.kind='manual_paid'),(select((p.started_at at time zone'UTC')+interval'1 month')at time zone'UTC'from public.doctor_saas_periods p where p.kind='manual_paid'),'server derives the configured calendar interval without client expiry');
select throws_ok($$update public.doctor_manual_received_funds set received_minor=1$$,'42501',null,'accepted funds cannot be destructively rewritten');
update public.doctor_manual_payment_reviewers set enabled=false,revision=2,approval_ref='SYNTHETIC_REVOKED'where user_id=pg_temp.id(2);
set local role authenticated;select pg_temp.claim(2);
select throws_ok($$select pg_temp.confirm('first',610)$$,'42501','DOCTOR_MANUAL_REVIEW_AUTHORITY_REQUIRED','receipt replay requires fresh independent reviewer authority');
select throws_ok($$select public.doctor_activate_manual_payment(((select value from results where name='first')->>'id')::uuid,1,pg_temp.id(620))$$,'42501','DOCTOR_MANUAL_REVIEW_AUTHORITY_REQUIRED','activation replay also respects current reviewer revocation');
reset role;
select ok(not has_table_privilege('authenticated','public.doctor_manual_received_funds','SELECT'),'raw received-funds evidence is not a client confirmation interface');
select * from finish();
rollback;
